import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Основные Принципы Возврата Времени","description":"","frontmatter":{},"headers":[],"relativePath":"ru/82-时间回溯基本原则.md","filePath":"ru/82-时间回溯基本原则.md"}'),i={name:"ru/82-时间回溯基本原则.md"};function o(l,t,h,n,p,s){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="основные-принципы-возврата-времени" tabindex="-1">Основные Принципы Возврата Времени <a class="header-anchor" href="#основные-принципы-возврата-времени" aria-label="Permalink to &quot;Основные Принципы Возврата Времени&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>82</td></tr><tr><td>Модуль</td><td>Межплоскостное взаимодействие и правила времени</td></tr><tr><td>Ключевые слова</td><td>возврат времени, сначала наблюдение потом вмешательство, стабильность линии времени, сохранение причинности, якорное закрепление</td></tr></tbody></table><h2 id="i-определение-и-сущность-возврата-времени" tabindex="-1">I. Определение и сущность возврата времени <a class="header-anchor" href="#i-определение-и-сущность-возврата-времени" aria-label="Permalink to &quot;I. Определение и сущность возврата времени&quot;">​</a></h2><p>Возврат времени обозначает поведение, при котором сознание, информация или материя отправляются назад к прошлому временному узлу через способность оперировать измерением времени в сети законов Якоря. В рамках законов Вселенной Хэнъюань время — не однонаправленный необратимый линейный поток, а оперируемое измерение сети законов. Однако операции в измерении времени несут чрезвычайно высокие риски и строгие ограничения; любое поведение возврата времени может вызвать возмущение причинных цепей, расщепление линий времени и даже колебания законов вселенского масштаба.</p><p>Сущность возврата времени — «создать канал возврата в измерении времени сети законов, позволяя конкретной информации или энергии распространяться в обратном направлении вдоль канала». Этот процесс потребляет огромное количество энергии Якоря, и чем древнее возврат и чем сложнее его содержание, тем экспоненциально больше потребление энергии. В настоящее время технические возможности Вселенной Хэнъюань поддерживают возврат лишь на уровне сознания и информации; полный возврат на уровне материи находится на стадии теоретических исследований.</p><p>Следует особо подчеркнуть, что возврат времени не равен «путешествию во времени». Возвращающийся входит в прошлое не в полной материальной форме, а достигает целевого временного узла в форме проекции сознания или пакета информации. Существование возвращающегося в прошлом периоде «полупрозрачно» — его можно наблюдать, но физическая способность взаимодействия строго ограничена. Сама эта конструкция — часть механизма безопасности возврата времени.</p><h2 id="ii-семь-основных-принципов-возврата-времени" tabindex="-1">II. Семь основных принципов возврата времени <a class="header-anchor" href="#ii-семь-основных-принципов-возврата-времени" aria-label="Permalink to &quot;II. Семь основных принципов возврата времени&quot;">​</a></h2><p>Операции возврата времени во Вселенной Хэнъюань следуют следующим семи основным принципам, установленным Собранием Якоря в форме особых резолюций и обладающим юридической силой, уступающей только Конституции:</p><table tabindex="0"><thead><tr><th>№ принципа</th><th>Название принципа</th><th>Основное содержание</th></tr></thead><tbody><tr><td>Первый принцип</td><td>Сначала наблюдение, потом ограниченное вмешательство</td><td>Любой возврат должен сначала завершить стадию чистого наблюдения; лишь после подтверждения отсутствия серьёзных рисков может проводиться ограниченное вмешательство</td></tr><tr><td>Второй принцип</td><td>Сохранение причинности</td><td>Возврат не должен изменять уже свершившиеся ключевые причинные цепи; причинные отклонения, возникшие из-за возврата, должны быть исправлены после завершения возврата</td></tr><tr><td>Третий принцип</td><td>Якорное закрепление</td><td>Все операции возврата должны использовать стабильный Якорь как начало временных координат; слепой возврат без Якоря запрещён</td></tr><tr><td>Четвёртый принцип</td><td>Минимальное воздействие</td><td>Все действия процесса возврата должны следовать принципу минимального воздействия, максимально уменьшая возмущение прошлой линии времени</td></tr><tr><td>Пятый принцип</td><td>Прослеживаемость</td><td>Каждый возврат должен полностью фиксировать журналы операций, включая личность возвращающегося, целевое время, наблюдавшееся содержание, действия вмешательства и оценку причинных отклонений</td></tr><tr><td>Шестой принцип</td><td>Запрет парадоксов</td><td>Строго запрещены любые операции, способные привести к временным парадоксам, включая, помимо прочего, парадокс убийства предка, информационный парадокс и онтологический парадокс</td></tr><tr><td>Седьмой принцип</td><td>Последующий аудит</td><td>После завершения возврата независимый Комитет Аудита Законов Времени должен провести последующий аудит, подтвердив отсутствие неконтролируемого возмущения линии времени</td></tr></tbody></table><p>Среди семи принципов «Сначала наблюдение, потом ограниченное вмешательство» — самый главный операционный принцип, а остальные шесть принципов развёртываются вокруг этого ядра. Подробные операционные спецификации этого принципа см. в документе 83 «Критерии Сначала Наблюдение, Потом Ограниченное Вмешательство».</p><h2 id="iii-иерархическое-управление-возвратом-времени" tabindex="-1">III. Иерархическое управление возвратом времени <a class="header-anchor" href="#iii-иерархическое-управление-возвратом-времени" aria-label="Permalink to &quot;III. Иерархическое управление возвратом времени&quot;">​</a></h2><p>По временному охвату и степени вмешательства операции возврата времени делятся на три уровня управления:</p><ol><li><p><strong>Возврат первого уровня (ближнее наблюдение)</strong>: временной охват возврата не превышает 100 лет стандартного времени своей плоскости, и проводится только чистое наблюдение без какого-либо вмешательства. Утверждается Управлением Плоскостей, при этом на процессе операции должны присутствовать не менее двух инспекторов законов времени.</p></li><li><p><strong>Возврат второго уровня (дальнее наблюдение)</strong>: временной охват возврата превышает 100 лет, но не превышает 10 000 лет, либо во время возврата требуется крайне лёгкое вмешательство (например, передача одной информации). Должен утверждаться Комитетом Законов Времени при Собрании Якоря с разработкой подробного плана экстренных мер по причинным отклонениям.</p></li><li><p><strong>Возврат третьего уровня (глубокое вмешательство)</strong>: временной охват возврата превышает 10 000 лет, либо во время возврата требуется существенное вмешательство. Должен утверждаться более чем двумя третями голосов пленарного заседания Собрания Якоря и проходить конституционный контроль Симбиотического Суда, подтверждающий соответствие вмешательства основным принципам Симбиотической Конституции.</p></li></ol><p>Возврат времени любого уровня запрещён для следующих целей: извлечение личной выгоды для отдельных лиц или малых групп, изменение судеб исторических личностей для удовлетворения личных желаний, искажение естественного процесса эволюции цивилизации, а также любые операции «исторического ревизионизма».</p><h2 id="iv-энергетические-и-технические-ограничения-возврата-времени" tabindex="-1">IV. Энергетические и технические ограничения возврата времени <a class="header-anchor" href="#iv-энергетические-и-технические-ограничения-возврата-времени" aria-label="Permalink to &quot;IV. Энергетические и технические ограничения возврата времени&quot;">​</a></h2><p>Энергопотребление возврата времени крайне велико. На примере возврата проекцией сознания: энергия, требуемая для возврата на 1 год, составляет около 10 000 стандартных единиц энергии; на 100 лет — около 1 миллиона стандартных единиц энергии; на 10 000 лет — около 10 миллиардов стандартных единиц энергии. Связь между энергопотреблением и временным охватом возврата приблизительно лог-линейна, но при пересечении крупных исторических узлов возникают энергетические пики — потому что плотность причинных цепей в крупных исторических узлах чрезвычайно высока, и операции возврата должны преодолевать большую причинную инерцию.</p><p>На техническом уровне возврат времени требует согласованной работы «устройства якорного закрепления законов времени» и «передающей решётки проекций сознания». Первое отвечает за установление стабильной временной координаты в целевом временном узле; вторая — за безопасную доставку проекции сознания возвращающегося и поддержание его существования в прошлом периоде. Всё оборудование возврата должно пройти сертификацию безопасности Надзорного Комитета Якоря; использование несертифицированного самодельного оборудования для операций возврата запрещено.</p><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Возврат времени — одна из самых мощных и самых опасных способностей оперирования законами Вселенной Хэнъюань. Семь основных принципов и система иерархического управления вместе составляют структуру безопасности возврата времени, чей основной дух — «благоговеть перед причинностью, действовать осторожно». Законные применения возврата времени ограничены археологическими исследованиями, восстановлением исторической истины и ранним предупреждением кризисов уровня вымирания; любое использование за пределами этого диапазона будет рассматриваться как осквернение законов вселенной.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>83-先观测后有限干涉准则 (Критерии Сначала Наблюдение, Потом Ограниченное Вмешательство)</li><li>89-时间悖论防控机制 (Механизм Профилактики и Контроля Временных Парадоксов)</li><li>84-考古协议总纲 (Общий Протокол Археологии)</li></ul>',21)])])}const b=a(i,[["render",o]]);export{c as __pageData,b as default};
